def find\_thumbnails\_page(rl, ca, pc, n=5):
 """Search backwards for most recent thumbnails page containing given product."""

 ix = 0
 rs = set()

 for r in rl[::-1]:

 if not pixel\_data.is\_thumbnails\_page(r):
 continue

 td = get\_thumbnails\_page\_products(r)
