def get\_thumbnails\_page\_products(r):

 catc = r.get('categoryCode')
 if not catc:
 return

 p2c = pixel\_data.get\_p2c()

 prdl = r.get('SFLY\_DTL', {}).get('productDetails') 
 if not prdl or type(prdl) is not list:
 return

 prdl = [p for p in prdl if catc in p2c.get(p['productCode'], {})]
 if not prdl:
 return

 return {
 'category': catc,
 'referrer': r['referrer'],
 'size': len(prdl),
 'products': prdl,
 }
def randint\_by\_dist(dist):

 ri = random.random() \* sum(dist)

 for i, f in enumerate(dist):
 ri -= f
 if ri < 0:
 return i
