 h2p, 
 d2h, 
 cps2d, 
 rmd, 
 u, 
 rl=None, 
 cart=None,
 inprods=None,
 exprods=None,
 thumbpages=False,
 max\_sequence=16,
 filter\_pips=False,
 debug=False,
):

 rl = pixel\_data.load\_user(u) if rl is None else rl
 cart = pixel\_data.get\_causal\_cart(rl) if cart is None else cart

 p2c = pixel\_data.get\_p2c()

 pcs = set()
 ctg = None

 pl0 = []
 pl1 = []
 pc0 = None

 for i, r in enumerate(rl):

 if not pixel\_data.is\_pip(r):
 continue

 p = pixel\_data.get\_product\_details(r, timestamp=True)

 pc = p.get('productCode')
 ca = p.get('categoryId')

 # dedup repeated products.
 if pc == pc0:
 continue
 pc0 = pc 

 if not ca and ctg and ctg in p2c.get(pc, {}):
 p['categoryId'] = ctg
 ca = ctg

 pl0.append(p)

 if pc in cart and pc not in pcs and ca and ca == ctg:
 pl1.append({
 'sequence': list(pl0), # copy list.
 'thumbs': find\_thumbnails\_page(rl[:i], ca, pc) if thumbpages else None,
 })

 if ca:
 ctg = ca

 pcs.add(pc)

 if not pl1:
 return

 s0 = random.choice(pl1)
 pl = s0['sequence'][-max\_sequence-1:] # the -1 for one extra element
 tb = s0['thumbs']

 ca = pl[-1]['categoryId']
 pc = pl[-1]['productCode']

 date = u['date']

 nsam = 32 if thumbpages else 48

 p2p0 = pixel\_data.get\_category\_products\_by\_popularity(rmd, date, ca)

 if filter\_pips:
 pcs = {p['productCode'] for p in pl[:-1]}
 p2p0 = {k: v for k, v in p2p0.items() if k not in pcs}

 # set of 32 most popular products in category.
 pps0 = set(list(p2p0)[:nsam]) 

 ppsx = set(pps0)
 ppsx.add(pc)

 # sample of 32 products from category tail.
 if len(p2p0) > nsam:
 pps0.update(random.sample(list(p2p0)[nsam:], min(nsam, len(p2p0) - nsam)))

 # sample of 32 products from corresponding thumbails page.
 if tb:
 prdl = random.sample(tb['products'], min(nsam, len(tb['products'])))
 pps0.update([t['productCode'] for t in prdl])

 if exprods:
 pps0 = pps0.difference(exprods)

 if not pps0:
 return

 pps1 = set(random.sample(list(pps0), min(64, len(pps0)))) 

 if pc in pps1:
 pps1.remove(pc)
 else:
 pps1.pop()

 if inprods and 'mix' in inprods:

 spli = utils.shuffled([k for k in p2p0 if k in inprods and k != pc])[:4]
 pps1 = pps1.difference(set(spli))
 spl0 = spli + utils.shuffled(list(pps1))[4:]

 elif inprods:
 spl0 = utils.shuffled([k for k in p2p0 if k in inprods and k != pc])

 else:
 spl0 = utils.shuffled(list(pps1))

 if not spl0:
 return

 ppl0 = [pc] + spl0
 ppl1 = [get\_product\_versions\_on\_date(d2h, cps2d, date, ca, pc0) for pc0 in ppl0]
 ppl2 = [list(v[1])[randint\_by\_dist(v[1].values())] for v in ppl1 if v]
 ppl3 = [h2p[h] for h in ppl2]

 # negative log likelihood correction.
 nllc = math.log(max(1, (len(p2p0) - len(ppsx)) / nsam))

 correction = {p['productCode']: 0 if p['productCode'] in ppsx else nllc for p in ppl3}
 popularity = {p['productCode']: p2p0.get(p['productCode']) or 0 for p in ppl3}

 if debug:
 return pl[:-1], ppl3, [pc for pc, v in zip(ppl0, ppl1) if v is None], s0, len(pl1)

 return {
 'pips': pl[:-1], 
 'positives': ppl3[:1],
 'negatives': ppl3[1:],
 'popularity': popularity,
 'correction': correction,
 'hashes': ppl2,
 'thumbs': prdl if tb else None,
 }

