 return user, created

 def generate\_otp(self, phone\_number=None):
 """Generate a new OTP for the given phone number."""
 otp = "".join(str(random.randint(0, 9)) for \_ in range(4))
 expire\_on = timezone.now() + timezone.timedelta(minutes=5)
 PhoneOTP.objects.create(phone\_number=phone\_number, otp=otp, expire\_on=expire\_on)
 return otp

 def verify\_otp(self, phone\_number, otp):
 """Verify the OTP for the given phone number."""
 try:
 phone\_otp = PhoneOTP.objects.exclude(is\_verified=True).get(
 phone\_number=phone\_number, otp=otp
 )
 except PhoneOTP.DoesNotExist:
 pass
 # log

 if timezone.now() > phone\_otp.expire\_on:
