 phone\_otp.verified\_on = timezone.now()
 phone\_otp.user = user
 phone\_otp.save()
 update\_third\_party\_log(third\_party\_log, user=user) 
 if not created:
 Token.objects.get\_or\_create(user=user)
 return user
 return None
